{"action": "replace_code", "code": "def solve(data):
    if not data['durations']:
        return {'duration': 0, 'path': []}

    memo = {}

    def get_best(node):
        if node in memo:
            return memo[node]

        # Начальная цепочка: только сам узел
        best_cost = data['durations'][node]
        best_path = [node]

        # Проверяем всех предшественников
        for parent in data['deps'][node]:
            parent_cost, parent_path = get_best(parent)
            new_cost = parent_cost + data['durations'][node]
            new_path = parent_path + [node]

            # Выбираем минимальную сумму, затем лексикографически минимальный путь
            if new_cost < best_cost or (new_cost == best_cost and new_path < best_path):
                best_cost = new_cost
                best_path = new_path

        memo[node] = (best_cost, best_path)
        return memo[node]

    # Вычисляем для всех узлов, которые имеют предшественников или сами являются корнями
    # Но нам нужно найти максимальную цепочку среди всех возможных путей
    # Сначала найдем все узлы, которые могут быть частью критического пути
    # Это все узлы, так как граф ацикличен и связный (в смысле зависимостей)

    # Находим все уникальные узлы
    all_nodes = set(data['durations'].keys())
    for deps in data['deps'].values():
        all_nodes.update(deps)

    # Вычисляем лучший путь для каждого узла
    results = {}
    for node in all_nodes:
        results[node] = get_best(node)

    # Находим максимальную сумму длительностей
    max_duration = -1
    best_global_path = None

    for node, (cost, path) in results.items():
        if cost > max_duration or (cost == max_duration and (best_global_path is None or path < best_global_path)):
            max_duration = cost
            best_global_path = path

    return {'duration': max_duration, 'path': best_global_path}"
}

