{"action": "replace_code", "code": "def solve(data):
    if not data['durations']:
        return {'duration': 0, 'path': []}

    memo = {}

    def get_best(node):
        if node in memo:
            return memo[node]

        duration = data['durations'][node]
        path = [node]

        parents = data['deps'].get(node, [])
        if not parents:
            memo[node] = (duration, path)
            return (duration, path)

        best_child = None
        best_child_cost = -1
        best_child_path = None

        for parent in parents:
            child_cost, child_path = get_best(parent)
            total_cost = child_cost + duration
            total_path = child_path + [node]

            if best_child is None:
                best_child_cost = total_cost
                best_child_path = total_path
                best_child = (total_cost, total_path)
            else:
                if total_cost > best_child_cost:
                    best_child_cost = total_cost
                    best_child_path = total_path
                    best_child = (total_cost, total_path)
                elif total_cost == best_child_cost:
                    if total_path < best_child_path:
                        best_child_cost = total_cost
                        best_child_path = total_path
                        best_child = (total_cost, total_path)

        memo[node] = best_child
        return best_child

    candidates = []
    for node in data['durations']:
        cost, path = get_best(node)
        candidates.append((cost, path))

    if not candidates:
        return {'duration': 0, 'path': []}

    best = min(candidates, key=lambda x: (x[0], x[1]))
    return {'duration': best[0], 'path': best[1]}
